#!/usr/bin/env node
// Usage: node cli.js run-1.xml run-2.xml [...more runs] [--fail-on-flaky]
const fs = require("fs");
const path = require("path");
const { parseJUnit, analyze, toMarkdown } = require("./src/flaky");

const argv = process.argv.slice(2);
const failOnFlaky = argv.includes("--fail-on-flaky");
const files = argv.filter((a) => !a.startsWith("--"));

if (files.length < 2) {
  console.error("Usage: node cli.js <run-1.xml> <run-2.xml> [...] [--fail-on-flaky]  (needs at least 2 runs)");
  process.exit(2);
}

const runs = files.map((f) => ({ name: path.basename(f), results: parseJUnit(fs.readFileSync(f, "utf8")) }));
const report = analyze(runs);
console.log(toMarkdown(report));
if (failOnFlaky && report.flaky.length > 0) process.exit(1);

// Compares JUnit XML results from several CI runs of the same suite and
// separates FLAKY tests (passed in some runs, failed in others) from tests
// that are genuinely BROKEN (failed every time they ran).

const ENTITIES = { "&amp;": "&", "&lt;": "<", "&gt;": ">", "&quot;": '"', "&apos;": "'" };
const decode = (s) => s.replace(/&(amp|lt|gt|quot|apos);/g, (m) => ENTITIES[m]);

function attrs(tag) {
  const out = {};
  for (const m of tag.matchAll(/([\w:-]+)="([^"]*)"/g)) out[m[1]] = decode(m[2]);
  return out;
}

// Minimal JUnit parser: enough for the XML that Jest, Playwright, pytest,
// Maven Surefire and most CI tools emit. Returns [{ id, status }].
function parseJUnit(xml) {
  const results = [];
  const re = /<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g;
  for (const m of xml.matchAll(re)) {
    const a = attrs(m[1]);
    if (!a.name) continue;
    const body = m[3] || "";
    const status = /<(failure|error)\b/.test(body) ? "failed" : /<skipped\b/.test(body) ? "skipped" : "passed";
    results.push({ id: a.classname ? `${a.classname} › ${a.name}` : a.name, status });
  }
  return results;
}

// runs: [{ name, results: [{ id, status }] }]
function analyze(runs) {
  const tests = new Map();
  for (const run of runs) {
    for (const r of run.results) {
      const t = tests.get(r.id) || { id: r.id, passed: 0, failed: 0, skipped: 0, failedIn: [] };
      t[r.status]++;
      if (r.status === "failed") t.failedIn.push(run.name);
      tests.set(r.id, t);
    }
  }
  const all = [...tests.values()].map((t) => ({ ...t, failRate: t.failed / (t.passed + t.failed || 1) }));
  const byRate = (a, b) => b.failRate - a.failRate || a.id.localeCompare(b.id);
  return {
    runs: runs.length,
    total: all.length,
    flaky: all.filter((t) => t.passed > 0 && t.failed > 0).sort(byRate),
    broken: all.filter((t) => t.failed > 0 && t.passed === 0).sort((a, b) => a.id.localeCompare(b.id)),
  };
}

const cell = (s) => String(s).replace(/\|/g, "\\|");

function toMarkdown(report) {
  const lines = [
    "## Flaky test report",
    "",
    `${report.runs} run(s), ${report.total} test(s): **${report.flaky.length} flaky**, **${report.broken.length} consistently failing**.`,
  ];
  if (report.flaky.length) {
    lines.push("", "### Flaky (passed and failed across runs)", "", "| Test | Failed / ran | Fail rate | Failed in |", "| --- | --- | --- | --- |");
    for (const t of report.flaky) {
      lines.push(`| ${cell(t.id)} | ${t.failed} / ${t.passed + t.failed} | ${Math.round(t.failRate * 100)}% | ${cell(t.failedIn.join(", "))} |`);
    }
  }
  if (report.broken.length) {
    lines.push("", "### Consistently failing (fix these first — they are not flaky)", "");
    for (const t of report.broken) lines.push(`- ${t.id}`);
  }
  if (!report.flaky.length && !report.broken.length) lines.push("", "No flaky or failing tests. 🎉");
  return lines.join("\n");
}

module.exports = { parseJUnit, analyze, toMarkdown };

const test = require("node:test");
const assert = require("node:assert");
const { parseJUnit, analyze, toMarkdown } = require("../src/flaky");

const xml = (cases) => `<testsuites><testsuite name="s">${cases}</testsuite></testsuites>`;

test("parses passed, failed, errored and skipped testcases", () => {
  const results = parseJUnit(
    xml(
      '<testcase classname="a" name="ok"/>' +
        '<testcase classname="a" name="bad"><failure message="x">boom</failure></testcase>' +
        '<testcase classname="a" name="err"><error/></testcase>' +
        '<testcase classname="a" name="skip"><skipped/></testcase>' +
        '<testcase name="no class &amp; entity"></testcase>'
    )
  );
  assert.deepStrictEqual(
    results.map((r) => [r.id, r.status]),
    [
      ["a › ok", "passed"],
      ["a › bad", "failed"],
      ["a › err", "failed"],
      ["a › skip", "skipped"],
      ["no class & entity", "passed"],
    ]
  );
});

test("mixed outcomes are flaky; always-failing is broken, not flaky", () => {
  const runs = [
    { name: "r1", results: [{ id: "t1", status: "failed" }, { id: "t2", status: "failed" }, { id: "t3", status: "passed" }] },
    { name: "r2", results: [{ id: "t1", status: "passed" }, { id: "t2", status: "failed" }, { id: "t3", status: "passed" }] },
    { name: "r3", results: [{ id: "t1", status: "failed" }, { id: "t2", status: "failed" }, { id: "t3", status: "skipped" }] },
  ];
  const report = analyze(runs);
  assert.deepStrictEqual(report.flaky.map((t) => [t.id, t.failed, t.passed, t.failedIn]), [["t1", 2, 1, ["r1", "r3"]]]);
  assert.deepStrictEqual(report.broken.map((t) => t.id), ["t2"]);
  assert.strictEqual(report.total, 3);
});

test("flaky tests are ranked by fail rate", () => {
  const runs = ["r1", "r2", "r3", "r4"].map((name, i) => ({
    name,
    results: [
      { id: "rarely", status: i === 0 ? "failed" : "passed" },
      { id: "often", status: i < 3 ? "failed" : "passed" },
    ],
  }));
  assert.deepStrictEqual(analyze(runs).flaky.map((t) => t.id), ["often", "rarely"]);
});

test("markdown report has a flaky table and a broken list", () => {
  const md = toMarkdown(
    analyze([
      { name: "r1", results: [{ id: "x | y", status: "failed" }, { id: "z", status: "failed" }] },
      { name: "r2", results: [{ id: "x | y", status: "passed" }, { id: "z", status: "failed" }] },
    ])
  );
  assert.match(md, /2 run\(s\), 2 test\(s\): \*\*1 flaky\*\*, \*\*1 consistently failing\*\*/);
  assert.match(md, /\| x \\\| y \| 1 \/ 2 \| 50% \| r1 \|/);
  assert.match(md, /- z/);
});
